using System.Globalization;using JobOrbit.Application.DTOs.AdminDashboard;using JobOrbit.Application.Interfaces;using JobOrbit.Domain.Enums;using Microsoft.EntityFrameworkCore;
namespace JobOrbit.Infrastructure.Persistence.Repositories;public sealed class AdminDashboardRepository(JobOrbitDbContext db):IAdminDashboardRepository
{public async Task<AdminDashboardStatsDto>StatsAsync(CancellationToken t=default){var month=new DateTime(DateTime.UtcNow.Year,DateTime.UtcNow.Month,1,0,0,0,DateTimeKind.Utc);return new(){TotalUsers=await db.Users.AsNoTracking().CountAsync(t),TotalCandidates=await db.Users.AsNoTracking().CountAsync(x=>x.Role==UserRole.Candidate,t),TotalRecruiters=await db.Users.AsNoTracking().CountAsync(x=>x.Role==UserRole.Recruiter,t),TotalHiringManagers=await db.Users.AsNoTracking().CountAsync(x=>x.Role==UserRole.HiringManager,t),ActiveJobs=await db.JobPostings.AsNoTracking().CountAsync(x=>x.Status==JobStatus.Published&&(x.ClosingAt==null||x.ClosingAt>DateTime.UtcNow),t),TotalApplications=await db.JobApplications.AsNoTracking().CountAsync(t),InterviewsScheduled=await db.Interviews.AsNoTracking().CountAsync(x=>x.Status!=InterviewStatus.Cancelled,t),HiredCandidates=await db.JobApplications.AsNoTracking().CountAsync(x=>x.Status==ApplicationStatus.Hired,t),ActiveOrganizations=await db.Organizations.AsNoTracking().CountAsync(t),NewUsersThisMonth=await db.Users.AsNoTracking().CountAsync(x=>x.CreatedAt>=month,t)};}
public async Task<IReadOnlyList<AdminUserGrowthDto>>UserGrowthAsync(DateTime f,DateTime to,CancellationToken t=default){var rows=await db.Users.AsNoTracking().Where(x=>x.CreatedAt>=f&&x.CreatedAt<=to).GroupBy(x=>new{x.CreatedAt.Year,x.CreatedAt.Month}).Select(g=>new{g.Key.Year,g.Key.Month,Candidates=g.Count(x=>x.Role==UserRole.Candidate),Recruiters=g.Count(x=>x.Role==UserRole.Recruiter),Managers=g.Count(x=>x.Role==UserRole.HiringManager),Admins=g.Count(x=>x.Role==UserRole.Administrator)}).ToListAsync(t);var result=new List<AdminUserGrowthDto>();for(var m=new DateTime(f.Year,f.Month,1,0,0,0,DateTimeKind.Utc);m<=to;m=m.AddMonths(1)){var x=rows.FirstOrDefault(x=>x.Year==m.Year&&x.Month==m.Month);var c=x?.Candidates??0;var r=x?.Recruiters??0;var h=x?.Managers??0;var a=x?.Admins??0;result.Add(new(){Period=m.ToString("yyyy-MM",CultureInfo.InvariantCulture),Label=m.ToString("MMM",CultureInfo.InvariantCulture),Candidates=c,Recruiters=r,HiringManagers=h,Admins=a,Total=c+r+h+a});}return result;}
public async Task<AdminApplicationOverviewDto>ApplicationOverviewAsync(CancellationToken t=default){var statuses=await db.JobApplications.AsNoTracking().GroupBy(x=>x.Status).Select(g=>new{g.Key,Count=g.Count()}).ToListAsync(t);var from=new DateTime(DateTime.UtcNow.Year,DateTime.UtcNow.Month,1,0,0,0,DateTimeKind.Utc).AddMonths(-5);var months=await db.JobApplications.AsNoTracking().Where(x=>x.AppliedAt>=from).GroupBy(x=>new{x.AppliedAt.Year,x.AppliedAt.Month}).Select(g=>new{g.Key.Year,g.Key.Month,Count=g.Count()}).ToListAsync(t);return new(){TotalApplications=await db.JobApplications.AsNoTracking().CountAsync(t),StatusCounts=Enum.GetValues<ApplicationStatus>().Select(s=>new AdminApplicationStatusCountDto{Status=s.ToString(),Count=statuses.FirstOrDefault(x=>x.Key==s)?.Count??0}).ToList(),MonthlyApplications=Enumerable.Range(0,6).Select(i=>from.AddMonths(i)).Select(m=>new AdminMonthlyApplicationDto{Period=m.ToString("yyyy-MM",CultureInfo.InvariantCulture),Label=m.ToString("MMM",CultureInfo.InvariantCulture),Count=months.FirstOrDefault(x=>x.Year==m.Year&&x.Month==m.Month)?.Count??0}).ToList()};}
public async Task<IReadOnlyList<AdminRecentActivityDto>>RecentActivityAsync(int limit,CancellationToken t=default)=>await db.AuditLogs.AsNoTracking().OrderByDescending(x=>x.CreatedAt).Take(limit).Select(x=>new AdminRecentActivityDto{ActivityId=x.Id,Action=x.Action,Description=x.Description??(x.Action+" on "+x.EntityName),ActorName=x.ActorNameSnapshot??(x.User==null?"System":x.User.FirstName+" "+x.User.LastName),ActorRole=x.ActorRoleSnapshot??(x.User==null?null:x.User.Role.ToString()),EntityType=x.EntityName,Severity=x.Severity.ToString(),OccurredAt=x.CreatedAt}).ToListAsync(t);
public async Task<AdminSystemHealthDto>SystemHealthAsync(CancellationToken t=default){var now=DateTime.UtcNow;try{var connected=await db.Database.CanConnectAsync(t);long records=0;if(connected)records=await db.Users.CountAsync(t)+await db.Organizations.CountAsync(t)+await db.JobPostings.CountAsync(t)+await db.JobApplications.CountAsync(t)+await db.Interviews.CountAsync(t)+await db.CandidateEvaluations.CountAsync(t);return new(){DatabaseStatus=connected?"Connected":"Unavailable",TotalDatabaseRecords=records,LastCheckedAt=now};}catch{return new(){DatabaseStatus="Unavailable",TotalDatabaseRecords=0,LastCheckedAt=now};}}
}
